<style>
:root{--ink:#203333;--muted:#647571;--line:#dce3df;--paper:#fff;--accent:#245f4d;--wash:#f5f6f2}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--wash);font:15px/1.65 system-ui,-apple-system,"Noto Sans KR",sans-serif}a{color:inherit;text-underline-offset:4px}button,input,textarea,select{font:inherit}button,.button{display:inline-flex;align-items:center;justify-content:center;padding:10px 18px;background:var(--accent);color:#fff;border:1px solid var(--accent);border-radius:7px;text-decoration:none;cursor:pointer;font-weight:650}button:hover,.button:hover{filter:brightness(.93)}button:disabled{opacity:.4;cursor:not-allowed}.secondary{background:#fff;color:var(--ink);border-color:var(--line)}.danger{background:#9b3e32;border-color:#9b3e32}input,textarea,select{width:100%;padding:10px 12px;border:1px solid #cbd6d0;border-radius:6px;background:white;color:var(--ink)}input:focus,textarea:focus,select:focus{outline:2px solid #70a68f;outline-offset:2px}input[type=checkbox]{width:20px;height:20px;vertical-align:middle;margin-right:8px}input[type=hidden]{display:none}textarea{min-height:100px;resize:vertical}label{display:block;font-weight:550}label>input,label>select,label>textarea{margin-top:6px}form{margin:0}.shop-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px max(24px,calc((100vw - 1200px)/2));background:white;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;font-size:21px;font-weight:750;text-decoration:none;white-space:nowrap}.brand-mark{background:var(--accent);color:#fff;font:italic 28px Georgia,serif;border-radius:8px;width:38px;text-align:center}.shop-header nav,.admin-nav{display:flex;gap:22px;align-items:center;flex-wrap:wrap}.shop-header nav a{text-decoration:none;font-size:14px}.admin-nav{padding:12px max(24px,calc((100vw - 1200px)/2));background:#e9eee8}.admin-nav a{padding:5px 9px;text-decoration:none}.admin-nav .active{background:white;border-radius:6px;font-weight:700}main{max-width:1200px;margin:0 auto;padding:32px 24px 70px;min-height:65vh}h1{font-size:30px;line-height:1.3;margin:0 0 12px;letter-spacing:-.04em}h2{font-size:20px;margin:0 0 16px}h3{font-size:17px}p{margin:10px 0}.muted,small{color:var(--muted)}.hero{padding:30px 0 35px}.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);font-weight:700}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px}.row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.row>*{width:auto}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.product-card{background:white;border:1px solid var(--line);border-radius:12px;overflow:hidden}.product-card>a{text-decoration:none}.product-card img,.placeholder{width:100%;aspect-ratio:4/3;object-fit:cover;background:#e8ede5}.placeholder{display:grid;place-items:center;font:italic 65px Georgia,serif;color:#a1b29d}.card-body{padding:18px}.card-body h2{font-size:17px;margin:0 0 10px}.price{font-size:21px;font-weight:750;font-variant-numeric:tabular-nums}.count,.badge{display:inline-block;font-size:12px;border-radius:20px;background:#e7eee8;padding:2px 9px;font-weight:650}.panel{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:24px;margin-bottom:22px}.empty{text-align:center;padding:70px 24px}.banner,.notice,.alert{padding:12px 18px;border-radius:7px;margin-bottom:20px}.banner{background:#fff1cf;color:#705d29}.notice{background:#e3f1e7;color:#225d3c}.alert{background:#fbe8e4;color:#8f342c}.cols{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,1fr);gap:24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.full{grid-column:1/-1}.stack>*+*{margin-top:16px}.product-image{width:100%;border-radius:12px;max-height:600px;object-fit:contain;background:#fff}.pre{white-space:pre-wrap;overflow-wrap:anywhere}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;text-align:left;font-size:14px}th{font-size:12px;color:var(--muted);font-weight:650;background:#f7f8f5;white-space:nowrap}th,td{padding:12px;border-bottom:1px solid var(--line);vertical-align:top}td{overflow-wrap:anywhere}td.num,th.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}td form.row{min-width:170px}td input[type=number]{width:100px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin:22px 0}.metric{padding:18px;border:1px solid var(--line);border-radius:10px;background:#fff}.metric strong{display:block;font-size:26px;font-variant-numeric:tabular-nums}.metric span{font-size:13px;color:var(--muted)}.summary-line{display:flex;justify-content:space-between;gap:20px;margin:12px 0}.summary-line.total{border-top:1px solid var(--line);padding-top:15px;font-weight:750;font-size:22px}.pagination{margin-top:25px;display:flex;gap:20px}.claim{border-top:1px solid var(--line);padding:20px 0}.claim:first-of-type{border-top:0}.highlight{color:#9b3e32;font-weight:750}.test-tag{color:#855d15;background:#fff1cf}.order-id{font:13px ui-monospace,monospace;overflow-wrap:anywhere}.policy{max-height:230px;overflow:auto;padding:15px;background:var(--wash);border-radius:8px}footer{max-width:1200px;margin:0 auto;padding:25px 24px 45px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}footer details{max-width:850px}details>summary{cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #70a68f;outline-offset:3px}@media(max-width:800px){.shop-header{padding:16px 20px;align-items:flex-start;flex-direction:column;gap:12px}.shop-header nav{gap:16px}.admin-nav{padding:10px 16px;gap:8px}main{padding:22px 16px 45px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.cols{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.panel{padding:18px}.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.toolbar{align-items:flex-start;flex-direction:column}h1{font-size:26px}.card-body{padding:12px}.price{font-size:18px}.row{gap:8px}}
